package com.witchersbestiary.test;
import com.witchersbestiary.enchantment.*;import com.witchersbestiary.registry.ModItems;
import net.fabricmc.fabric.api.gametest.v1.FabricGameTest;import net.minecraft.test.*;import net.minecraft.entity.*;import net.minecraft.entity.attribute.EntityAttributes;import net.minecraft.entity.mob.*;import net.minecraft.entity.passive.*;import net.minecraft.entity.player.*;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.item.*;import net.minecraft.enchantment.*;import net.minecraft.registry.*;import net.minecraft.registry.entry.RegistryEntry;import net.minecraft.registry.tag.EnchantmentTags;import net.minecraft.util.*;import net.minecraft.util.math.*;import java.util.*;
public final class SwordEnchantmentTests implements FabricGameTest {
 private static final String EMPTY="witchersbestiary:village_board_arena";
 private RegistryEntry<Enchantment> entry(TestContext c,RegistryKey<Enchantment> key){return c.getWorld().getRegistryManager().get(RegistryKeys.ENCHANTMENT).getEntry(key).orElseThrow();}
 private ItemStack sword(TestContext c,RegistryKey<Enchantment> key,int level){var s=new ItemStack(Items.DIAMOND_SWORD);if(key!=null)s.addEnchantment(entry(c,key),level);return s;}
 private ServerPlayerEntity player(TestContext c,ItemStack sword){c.getWorld().getServer().setPvpEnabled(true);var data=net.minecraft.server.network.ConnectedClientData.createDefault(new com.mojang.authlib.GameProfile(UUID.randomUUID(),"wb"+UUID.randomUUID().toString().substring(0,8)),false);var p=new ServerPlayerEntity(c.getWorld().getServer(),c.getWorld(),data.gameProfile(),data.syncedOptions());var connection=new net.minecraft.network.ClientConnection(net.minecraft.network.NetworkSide.SERVERBOUND);new io.netty.channel.embedded.EmbeddedChannel(connection);c.getWorld().getServer().getPlayerManager().onPlayerConnect(connection,p,data);for(int tick=0;tick<61;tick++)p.tick();p.changeGameMode(net.minecraft.world.GameMode.SURVIVAL);p.setInvulnerable(false);p.setNoGravity(true);p.getInventory().clear();p.getInventory().setStack(0,sword);p.setHealth(10);p.getHungerManager().setFoodLevel(10);p.getHungerManager().setSaturationLevel(0);p.getAttributeInstance(EntityAttributes.GENERIC_ATTACK_DAMAGE).setBaseValue(10);p.getAttributeInstance(EntityAttributes.GENERIC_ATTACK_SPEED).setBaseValue(1024);return p;}
 private <T extends LivingEntity>T target(TestContext c,EntityType<T> type,int x,int z){var e=type.create(c.getWorld());var pos=c.getAbsolutePos(new BlockPos(x,2,z));e.refreshPositionAndAngles(pos.getX()+.5,pos.getY(),pos.getZ()+.5,180,0);if(e instanceof ZombieEntity)e.equipStack(EquipmentSlot.HEAD,new ItemStack(Items.CARVED_PUMPKIN));e.setNoGravity(true);e.noClip=true;e.setInvulnerable(false);if(e instanceof MobEntity mob){mob.setAiDisabled(true);mob.setPersistent();}c.getWorld().spawnEntity(e);e.getAttributeInstance(EntityAttributes.GENERIC_MAX_HEALTH).setBaseValue(200);e.setHealth(200);e.getAttributeInstance(EntityAttributes.GENERIC_ARMOR).setBaseValue(0);return e;}
 private float hit(ServerPlayerEntity p,LivingEntity e){p.refreshPositionAndAngles(e.getX(),e.getY(),e.getZ()-2,0,0);p.setHeadYaw(0);p.setSprinting(true);p.setOnGround(true);p.fallDistance=0;e.timeUntilRegen=0;float before=e.getHealth();p.attack(e);e.setVelocity(Vec3d.ZERO);return before-e.getHealth();}
 private void allowSweep(Runnable action){
  if(!net.fabricmc.loader.api.FabricLoader.getInstance().isModLoaded("bettercombat")){action.run();return;}
  try{var config=Class.forName("net.bettercombat.BetterCombatMod").getField("config").get(null);var field=config.getClass().getField("allow_vanilla_sweeping");boolean previous=field.getBoolean(config);try{field.setBoolean(config,true);action.run();}finally{field.setBoolean(config,previous);}}catch(ReflectiveOperationException error){throw new IllegalStateException(error);}
 }
 private void close(Entity...entities){for(var e:entities)e.discard();}
 private void near(TestContext c,double actual,double expected,String message){c.assertTrue(Math.abs(actual-expected)<.025,message+": "+actual+" expected "+expected);}
 @GameTest(templateName=EMPTY,batchId="enchantment-registry")
 public void fourDefinitionsTableBooksAnvilAndAllCompatibilityPairs(TestContext c){var keys=List.of(SwordEnchantments.BANE,SwordEnchantments.FROST,SwordEnchantments.BLOOD,SwordEnchantments.RUNIC);var r=c.getWorld().getRegistryManager().get(RegistryKeys.ENCHANTMENT);var p=player(c,sword(c,null,0));p.addExperienceLevels(100);var pool=r.getEntryList(EnchantmentTags.IN_ENCHANTING_TABLE).orElseThrow();var candidates=EnchantmentHelper.getPossibleEntries(40,new ItemStack(Items.DIAMOND_SWORD),pool.stream());
 for(var key:keys){var e=entry(c,key);c.assertTrue(e.value().getMaxLevel()==3&&e.value().isSupportedItem(new ItemStack(Items.IRON_SWORD))&&e.value().isPrimaryItem(new ItemStack(Items.NETHERITE_SWORD))&&!e.value().isSupportedItem(new ItemStack(Items.IRON_AXE)),"Sword-only vanilla definitions "+key);c.assertTrue(candidates.stream().anyMatch(v->v.enchantment.equals(e)&&v.level==3),"TierIII occurs in real table pool "+key);var h=new net.minecraft.screen.AnvilScreenHandler(701,p.getInventory());h.getSlot(0).setStack(new ItemStack(Items.IRON_SWORD));h.getSlot(1).setStack(EnchantedBookItem.forEnchantment(new EnchantmentLevelEntry(e,3)));h.updateResult();c.assertTrue(EnchantmentHelper.getLevel(e,h.getSlot(2).getStack())==3,"Actual anvil accepts enchanted book "+key);}
 for(int a=0;a<4;a++)for(int b=a+1;b<4;b++)c.assertTrue(Enchantment.canBeCombined(entry(c,keys.get(a)),entry(c,keys.get(b))),"All six WB pairs compatible");c.assertTrue(!Enchantment.canBeCombined(entry(c,SwordEnchantments.BANE),entry(c,Enchantments.SHARPNESS))&&!Enchantment.canBeCombined(entry(c,SwordEnchantments.BANE),entry(c,Enchantments.SMITE))&&!Enchantment.canBeCombined(entry(c,SwordEnchantments.BANE),entry(c,Enchantments.BANE_OF_ARTHROPODS)),"Damage exclusivity limits stacking");c.assertTrue(!Enchantment.canBeCombined(entry(c,SwordEnchantments.FROST),entry(c,Enchantments.FIRE_ASPECT))&&Enchantment.canBeCombined(entry(c,SwordEnchantments.BLOOD),entry(c,Enchantments.SHARPNESS)),"Thermal exclusivity and other vanilla combinations");var found=new HashSet<RegistryKey<Enchantment>>();for(int seed=0;seed<512;seed++)for(var e:EnchantmentHelper.generateEnchantments(net.minecraft.util.math.random.Random.create(seed),new ItemStack(Items.BOOK),30,pool.stream()))for(var key:keys)if(e.enchantment.matchesKey(key))found.add(key);c.assertTrue(found.containsAll(keys),"All four genuinely generated for ordinary books, not command-only");close(p);c.complete();}
 @GameTest(templateName=EMPTY,batchId="enchantment-bane")
 public void baneLevelsCompositionAndNoPlayerOrMerchantBonus(TestContext c){var p=player(c,sword(c,null,0));var plain=target(c,com.witchersbestiary.entity.ModEntities.GHOUL,2,4);float base=hit(p,plain);c.assertTrue(base>0,"Real melee baseline");for(int level=1;level<=3;level++){p.getInventory().setStack(0,sword(c,SwordEnchantments.BANE,level));var mob=target(c,com.witchersbestiary.entity.ModEntities.GHOUL,6+level*4,4);near(c,hit(p,mob),base*(1+new double[]{.05,.09,.13}[level-1]),"Bane level "+level);close(mob);}var other=player(c,ItemStack.EMPTY);other.refreshPositionAndAngles(plain.getX()+8,plain.getY(),plain.getZ(),180,0);other.setHealth(20);near(c,hit(p,other),base,"No player Bane bonus");var merchant=target(c,com.witchersbestiary.merchant.ArcaneMerchants.TYPE,22,4);near(c,hit(p,merchant),base,"No merchant Bane bonus");
 p.addStatusEffect(new net.minecraft.entity.effect.StatusEffectInstance(com.witchersbestiary.registry.ModEffects.NECROPHAGE_HUNTER,3600,0));p.getInventory().setStack(8,new ItemStack(ModItems.NECROPHAGE_OIL));var specialized=target(c,com.witchersbestiary.entity.ModEntities.GHOUL,26,4);near(c,hit(p,specialized),base*1.13*1.25*1.15,"Exactly one Bane, elixir and oil multiplication");c.assertTrue(com.witchersbestiary.alchemy.InventoryOils.charges(p.getInventory().getStack(8))==39,"Exactly one oil charge consumed");close(p,plain,other,merchant,specialized);c.complete();}
 @GameTest(templateName=EMPTY,batchId="enchantment-frost",tickLimit=120)
 public void frostLevelsDurationGapMissAndInvulnerableTarget(TestContext c){var p=player(c,sword(c,SwordEnchantments.FROST,3));var e=target(c,EntityType.ZOMBIE,2,4);p.swingHand(Hand.MAIN_HAND);c.assertTrue(!e.hasStatusEffect(net.minecraft.entity.effect.StatusEffects.SLOWNESS),"Swing/miss has no frost");e.setInvulnerable(true);hit(p,e);c.assertTrue(!e.hasStatusEffect(net.minecraft.entity.effect.StatusEffects.SLOWNESS),"Invulnerable target cannot trigger frost");e.setInvulnerable(false);c.assertTrue(hit(p,e)>0,"Real successful hit");var status=e.getStatusEffect(net.minecraft.entity.effect.StatusEffects.SLOWNESS);c.assertTrue(status!=null&&status.getDuration()==50&&status.getAmplifier()==1,"TierIII exact50ticks/slownessII");
 c.runAtTick(20,()->{int remaining=e.getStatusEffect(net.minecraft.entity.effect.StatusEffects.SLOWNESS).getDuration();hit(p,e);c.assertTrue(e.getStatusEffect(net.minecraft.entity.effect.StatusEffects.SLOWNESS).getDuration()<=remaining,"Fast hit cannot refresh frost");});c.runAtTick(55,()->c.assertTrue(!e.hasStatusEffect(net.minecraft.entity.effect.StatusEffects.SLOWNESS),"There is a real movement gap before60tick readiness"));c.runAtTick(65,()->{p.getInventory().setStack(0,sword(c,SwordEnchantments.FROST,1));hit(p,e);c.assertTrue(e.getStatusEffect(net.minecraft.entity.effect.StatusEffects.SLOWNESS).getDuration()==30&&e.getStatusEffect(net.minecraft.entity.effect.StatusEffects.SLOWNESS).getAmplifier()==0,"TierI30ticks/slownessI");var two=target(c,EntityType.ZOMBIE,8,4);p.getInventory().setStack(0,sword(c,SwordEnchantments.FROST,2));hit(p,two);c.assertTrue(two.getStatusEffect(net.minecraft.entity.effect.StatusEffects.SLOWNESS).getDuration()==50&&two.getStatusEffect(net.minecraft.entity.effect.StatusEffects.SLOWNESS).getAmplifier()==0,"TierII50ticks/slownessI");close(p,e,two);c.complete();});}
 @GameTest(templateName=EMPTY,batchId="enchantment-harvest",tickLimit=100)
 public void bloodLevelsCooldownCapAndIndirectRejection(TestContext c){var p=player(c,sword(c,SwordEnchantments.BLOOD,3));var e=target(c,EntityType.ZOMBIE,2,4);p.swingHand(Hand.MAIN_HAND);near(c,p.getHealth(),10,"Miss never heals");e.damage(c.getWorld().getDamageSources().playerAttack(p),2);near(c,p.getHealth(),10,"Periodic/ability-labelled player damage outside a sword attack cannot heal");hit(p,e);near(c,p.getHealth(),11.5,"TierIII heal1.5HP");hit(p,e);near(c,p.getHealth(),11.5,"Three-second individual cooldown");for(int level=1;level<=2;level++){var other=player(c,sword(c,SwordEnchantments.BLOOD,level));LivingEntity mob=level==1?target(c,EntityType.SLIME,8+level*4,4):target(c,EntityType.ZOMBIE,8+level*4,4);hit(other,mob);near(c,other.getHealth(),10+level*.5,"Independent player heal level"+level+" including vanilla Slime");close(other,mob);}c.runAtTick(65,()->{p.setHealth(19.75f);hit(p,e);near(c,p.getHealth(),20,"Heal cannot exceed max health");close(p,e);c.complete();});}
 @GameTest(templateName=EMPTY,batchId="enchantment-friendlies")
 public void friendlyDummyMerchantVillagerAndPetNeverFuelHealingOrRunes(TestContext c){var weapon=sword(c,SwordEnchantments.BLOOD,3);weapon.addEnchantment(entry(c,SwordEnchantments.RUNIC),3);var p=player(c,weapon);var merchant=target(c,com.witchersbestiary.merchant.ArcaneMerchants.TYPE,2,4);var villager=target(c,EntityType.VILLAGER,7,4);var cow=target(c,EntityType.COW,12,4);var stand=target(c,EntityType.ARMOR_STAND,17,4);var pet=target(c,EntityType.WOLF,22,4);pet.setOwner(p);for(var e:List.of(merchant,villager,cow,stand,pet)){hit(p,e);near(c,p.getHealth(),10,"Friendly/decorative targets cannot heal");c.assertTrue(weapon.getOrDefault(SwordEnchantments.RUNIC_STATE,RunicState.EMPTY).charges()==0,"Friendly targets cannot charge AoE");}close(p,merchant,villager,cow,stand,pet);c.complete();}
 @GameTest(templateName=EMPTY,batchId="enchantment-shield",tickLimit=40)
 public void fullyBlockedPlayerHitCannotSlowHealOrCharge(TestContext c){var weapon=sword(c,SwordEnchantments.FROST,3);weapon.addEnchantment(entry(c,SwordEnchantments.BLOOD),3);weapon.addEnchantment(entry(c,SwordEnchantments.RUNIC),3);var p=player(c,weapon);var defender=player(c,ItemStack.EMPTY);var pos=c.getAbsolutePos(new BlockPos(2,2,4));defender.refreshPositionAndAngles(pos.getX(),pos.getY(),pos.getZ(),180,0);defender.setHeadYaw(180);defender.setHealth(20);defender.getInventory().offHand.set(0,new ItemStack(Items.SHIELD));defender.setCurrentHand(Hand.OFF_HAND);for(int tick=1;tick<=7;tick++)c.runAtTick(tick,()->defender.playerTick());c.runAtTick(8,()->{c.assertTrue(defender.isBlocking(),"Real vanilla shield active");near(c,hit(p,defender),0,"Fully blocked actual damage");near(c,p.getHealth(),10,"Shield block cannot heal");c.assertTrue(!defender.hasStatusEffect(net.minecraft.entity.effect.StatusEffects.SLOWNESS)&&weapon.getOrDefault(SwordEnchantments.RUNIC_STATE,RunicState.EMPTY).charges()==0,"Shield block has no frost or charge");close(p,defender);c.complete();});}
 @GameTest(templateName=EMPTY,batchId="enchantment-rune",tickLimit=80)
 public void runicThresholdRadiusFriendliesAndNoRecursiveProc(TestContext c){var weapon=sword(c,SwordEnchantments.RUNIC,3);weapon.addEnchantment(entry(c,SwordEnchantments.BLOOD),3);var p=player(c,weapon);var primary=target(c,EntityType.ZOMBIE,2,4);var near=target(c,EntityType.ZOMBIE,4,4);var far=target(c,EntityType.ZOMBIE,6,4);var ally=target(c,EntityType.VILLAGER,3,4);for(int i=0;i<3;i++){int tick=2+i*5;c.runAtTick(tick,()->{primary.refreshPositionAndAngles(c.getAbsolutePos(new BlockPos(2,2,4)).getX()+.5,primary.getY(),c.getAbsolutePos(new BlockPos(2,2,4)).getZ()+.5,180,0);hit(p,primary);});}c.runAtTick(18,()->{near(c,near.getHealth(),198,"Radius3 pulse small magic damage");near(c,far.getHealth(),200,"Outside radius unaffected");near(c,ally.getHealth(),200,"Friendly NPC inside ring safe");near(c,p.getHealth(),11.5,"Pulse cannot activate extra lifesteal");c.assertTrue(weapon.get(SwordEnchantments.RUNIC_STATE).charges()==0,"Pulse consumed charge and did not recurse");var beforeCharge=weapon.get(SwordEnchantments.RUNIC_STATE);hit(p,primary);c.assertTrue(weapon.get(SwordEnchantments.RUNIC_STATE).charges()==beforeCharge.charges(),"Pulse cooldown blocks immediate new charge");close(p,primary,near,far,ally);c.complete();});}
 @GameTest(templateName=EMPTY,batchId="enchantment-state",tickLimit=60)
 public void weaponBoundStateAndCooldownSerialization(TestContext c){var a=sword(c,SwordEnchantments.RUNIC,3);var b=sword(c,SwordEnchantments.RUNIC,3);var p=player(c,a);var e=target(c,EntityType.ZOMBIE,2,4);c.runAtTick(2,()->hit(p,e));c.runAtTick(7,()->{hit(p,e);c.assertTrue(a.get(SwordEnchantments.RUNIC_STATE).charges()==2,"First weapon holds its own two charges");var copy=ItemStack.fromNbt(c.getWorld().getRegistryManager(),a.encode(c.getWorld().getRegistryManager())).orElseThrow();c.assertTrue(copy.get(SwordEnchantments.RUNIC_STATE).equals(a.get(SwordEnchantments.RUNIC_STATE))&&SwordEnchantments.level(copy,SwordEnchantments.RUNIC,p)==3,"Component and enchantment roundtrip");p.getInventory().setStack(0,b);});c.runAtTick(12,()->{hit(p,e);c.assertTrue(b.getOrDefault(SwordEnchantments.RUNIC_STATE,RunicState.EMPTY).charges()==1&&a.get(SwordEnchantments.RUNIC_STATE).charges()==2,"No charge transfer between different swords: A="+a.get(SwordEnchantments.RUNIC_STATE)+" B="+b.get(SwordEnchantments.RUNIC_STATE)+" targetHP="+e.getHealth());var state=(SwordEnchantmentState)p;state.bestiary$harvestReady(9000);var n=new net.minecraft.nbt.NbtCompound();p.writeCustomDataToNbt(n);c.assertTrue(n.getLong("WitcherHarvestReady")==9000,"Entity cooldown persisted alongside ordinary player data");close(p,e);c.complete();});}
 @GameTest(templateName=EMPTY,batchId="enchantment-config")
 public void configurationRangesAreFiniteAndKeepFrostGaps(TestContext c){var p=new Properties();p.setProperty("enchantments.monstersBane3","NaN");p.setProperty("enchantments.frostTicks3","999");p.setProperty("enchantments.frostCooldown","1");p.setProperty("enchantments.bloodCooldown","-20");p.setProperty("enchantments.runicDamage","999");p.setProperty("enchantments.runicMaxTargets","999");p.setProperty("enchantments.runicRadius3","999");var s=new EnchantmentSettings(p);c.assertTrue(s.bane(3)==.13&&s.frostCooldown>=s.frost(3)+10&&s.bloodCooldown==40&&s.pulseDamage==4&&s.maxTargets==12&&s.radius(3)==4,"Untrusted/out-of-range config remains bounded and finite");c.complete();}
 @GameTest(templateName=EMPTY,batchId="enchantment-contract")
 public void contractKatakanAndProgressiveStatsRemainFrozen(TestContext c){var p=player(c,sword(c,null,0));var kind="katakan";var profile=com.witchersbestiary.contracts.procedural.ProceduralProfile.generate(17,kind);var definition=com.witchersbestiary.contracts.procedural.ProceduralHunts.snapshot(com.witchersbestiary.contracts.Contracts.DEFINITIONS.find(com.witchersbestiary.contracts.procedural.ProceduralHunts.id(kind)),profile);var contract=new com.witchersbestiary.contracts.ContractInstance(UUID.randomUUID(),p.getUuid(),definition,System.currentTimeMillis());contract.procedural=profile;var e=target(c,com.witchersbestiary.entity.ModEntities.KATAKAN,2,4);com.witchersbestiary.contracts.procedural.ProceduralHunts.bind(e,contract);com.witchersbestiary.combat.ProgressiveDifficulty.freshSpawn(e);com.witchersbestiary.combat.ProgressiveDifficulty.refresh(e,2);e.setHealth(e.getMaxHealth());double max=e.getMaxHealth();int modifiers=e.getAttributeInstance(EntityAttributes.GENERIC_MAX_HEALTH).getModifiers().size();float baseline=hit(p,e);p.getInventory().setStack(0,sword(c,SwordEnchantments.BANE,3));near(c,hit(p,e),baseline*1.13,"Contract Katakan receives one universal bonus");c.assertTrue(e.getMaxHealth()==max&&e.getAttributeInstance(EntityAttributes.GENERIC_MAX_HEALTH).getModifiers().size()==modifiers&&com.witchersbestiary.contracts.procedural.ProceduralHunts.binding(e)!=null,"Hit never recalculates maxhealth/progression/contract identity");close(p,e);c.complete();}
 @GameTest(templateName=EMPTY,batchId="enchantment-sweep")
 public void realSweepProcessesAllVictimsButChargesAndHealsOnce(TestContext c){var weapon=sword(c,SwordEnchantments.BANE,3);for(var key:List.of(SwordEnchantments.FROST,SwordEnchantments.BLOOD,SwordEnchantments.RUNIC))weapon.addEnchantment(entry(c,key),3);var p=player(c,weapon);var a=target(c,com.witchersbestiary.entity.ModEntities.GHOUL,2,4);var b=target(c,com.witchersbestiary.entity.ModEntities.GHOUL,3,4);p.refreshPositionAndAngles(a.getX(),a.getY(),a.getZ()-2,0,0);p.setOnGround(true);p.setHeadYaw(0);p.setSprinting(false);allowSweep(()->p.attack(a));c.assertTrue(a.getHealth()<200&&b.getHealth()<200&&a.hasStatusEffect(net.minecraft.entity.effect.StatusEffects.SLOWNESS)&&b.hasStatusEffect(net.minecraft.entity.effect.StatusEffects.SLOWNESS),"Real sweep secondary target not dropped");c.assertTrue(weapon.get(SwordEnchantments.RUNIC_STATE).charges()==1,"One attack tick charges once across multiple actual victims");near(c,p.getHealth(),11.5,"Sweep lifesteal once per owner cooldown");close(p,a,b);c.complete();}
 @GameTest(templateName=EMPTY,batchId="enchantment-rune-cap",tickLimit=60)
 public void runeLowerTiersAndMaximumTargetsAreBounded(TestContext c){var actors=new ArrayList<Entity>();for(int level=1;level<=2;level++){final int tier=level;var weapon=sword(c,SwordEnchantments.RUNIC,level);var p=player(c,weapon);var primary=target(c,EntityType.ZOMBIE,2+level*12,4);actors.add(p);actors.add(primary);var crowd=new ArrayList<LivingEntity>();for(int i=0;i<16;i++){var mob=target(c,EntityType.ZOMBIE,2+level*12,4);mob.refreshPositionAndAngles(primary.getX()+1.6,primary.getY(),primary.getZ(),0,0);crowd.add(mob);actors.add(mob);}int threshold=level==1?5:4;for(int i=0;i<threshold;i++){int index=i;c.runAtTick(2+i*5,()->{float actual=hit(p,primary);c.assertTrue(actual>0,"Actual crowd primary hit tier="+tier+" index="+index+" health="+primary.getHealth()+" p="+p.getPos()+" main="+p.getMainHandStack()+" alive="+p.isAlive()+" removed="+p.isRemoved()+" targetAlive="+primary.isAlive()+" invulnerable="+primary.isInvulnerable());if(index<threshold-1)c.assertTrue(weapon.getOrDefault(SwordEnchantments.RUNIC_STATE,RunicState.EMPTY).charges()==index+1,"Exact lower-tier threshold "+tier);});}c.runAtTick(30,()->c.assertTrue(crowd.stream().filter(m->m.getHealth()<200).count()==8&&crowd.stream().allMatch(m->m.getHealth()>=198),"Exactly eight small pulse victims; no recursion; tier"+tier+" health="+crowd.stream().map(m->m.getHealth()).toList()));}c.runAtTick(35,()->{close(actors.toArray(Entity[]::new));c.complete();});}
 @GameTest(templateName="witchersbestiary:village_board_arena",batchId="enchantment-fists")
 public void officialDuelsAndNpcFistsRejectEnchantedWeaponDamage(TestContext c){for(int x=0;x<48;x++)for(int z=0;z<48;z++){c.setBlockState(new BlockPos(x,1,z),net.minecraft.block.Blocks.STONE);for(int y=2;y<20;y++)c.setBlockState(new BlockPos(x,y,z),net.minecraft.block.Blocks.AIR);}var stone=c.getAbsolutePos(new BlockPos(12,2,24));c.getWorld().setBlockState(stone,com.witchersbestiary.fist.DuelStone.BLOCK.getDefaultState());var a=player(c,ItemStack.EMPTY);var b=player(c,ItemStack.EMPTY);a.refreshPositionAndAngles(stone.getX(),stone.getY(),stone.getZ()-2,0,0);b.refreshPositionAndAngles(stone.getX(),stone.getY(),stone.getZ()+2,180,0);com.witchersbestiary.fist.DuelSessions.interact(a,stone);com.witchersbestiary.fist.DuelSessions.interact(b,stone);var duel=com.witchersbestiary.fist.DuelSessions.get(a);c.assertTrue(duel!=null,"Official duel created");com.witchersbestiary.fist.DuelSessions.control(a,duel.id,0);com.witchersbestiary.fist.DuelSessions.control(b,duel.id,0);var weapon=sword(c,SwordEnchantments.BANE,3);for(var key:List.of(SwordEnchantments.FROST,SwordEnchantments.BLOOD,SwordEnchantments.RUNIC))weapon.addEnchantment(entry(c,key),3);a.getInventory().setStack(0,weapon);near(c,hit(a,b),0,"Forged equipped sword cannot damage an official duelist");near(c,a.getHealth(),10,"Virtual session cannot grant healing");c.assertTrue(!b.hasStatusEffect(net.minecraft.entity.effect.StatusEffects.SLOWNESS)&&!weapon.contains(SwordEnchantments.RUNIC_STATE),"No enchanted effects in duel");com.witchersbestiary.fist.DuelSessions.leave(a,com.witchersbestiary.fist.DuelSessions.Result.SURRENDER);duel.deadline=0;com.witchersbestiary.fist.DuelSessions.tick(a.getServer());a.getInventory().setStack(0,ItemStack.EMPTY);var npc=com.witchersbestiary.fist.FistRegistry.NOVICE.create(c.getWorld());npc.refreshPositionAndAngles(a.getX()+1,a.getY(),a.getZ(),0,0);c.getWorld().spawnEntity(npc);com.witchersbestiary.fist.FistFights.invite(a,npc);c.assertTrue(com.witchersbestiary.fist.FistFights.confirm(a,npc),"Official NPC fist bout created");a.getInventory().setStack(0,weapon);near(c,hit(a,npc),0,"NPC virtual fight cannot be bypassed");com.witchersbestiary.fist.FistFights.cancel(a);close(a,b,npc);c.complete();}

 @GameTest(templateName=EMPTY,batchId="enchantment-pvp",tickLimit=50)
 public void serverPvpOffAndPulseNeverDamagePlayers(TestContext c){var weapon=sword(c,SwordEnchantments.RUNIC,3);weapon.addEnchantment(entry(c,SwordEnchantments.FROST),3);weapon.addEnchantment(entry(c,SwordEnchantments.BLOOD),3);var p=player(c,weapon);var bystander=player(c,ItemStack.EMPTY);bystander.setHealth(20);boolean previous=c.getWorld().getServer().isPvpEnabled();try{c.getWorld().getServer().setPvpEnabled(false);near(c,hit(p,bystander),0,"pvp=false blocks the original attack");near(c,p.getHealth(),10,"Rejected PvP has no healing");c.assertTrue(!bystander.hasStatusEffect(net.minecraft.entity.effect.StatusEffects.SLOWNESS)&&!weapon.contains(SwordEnchantments.RUNIC_STATE),"No hidden PvP procs");}finally{c.getWorld().getServer().setPvpEnabled(previous);}var primary=target(c,com.witchersbestiary.entity.ModEntities.GHOUL,2,4);var other=target(c,com.witchersbestiary.entity.ModEntities.GHOUL,4,4);bystander.refreshPositionAndAngles(other.getX(),other.getY(),other.getZ(),0,0);for(int i=0;i<3;i++)c.runAtTick(2+i*5,()->hit(p,primary));c.runAtTick(18,()->{near(c,other.getHealth(),198,"Pulse really occurred in occupied radius");near(c,bystander.getHealth(),20,"Pulse never damages players even with ordinary PvP enabled");close(p,bystander,primary,other);c.complete();});}

}
